// Recibe todos los posts de Blogger y construye el mapa cluster→pilar
const config = $('⚙️ CONFIG').first().json;
const LABEL_PILAR = config.LABEL_PILAR.toLowerCase().trim();

const raw = $input.first().json;
const allPosts = raw.items || [];

if (allPosts.length === 0) {
  return [{ json: { error: 'No se encontraron posts publicados en el blog.' } }];
}

// Mapa id → post con labels normalizadas
const byId = {};
allPosts.forEach(p => {
  byId[p.id] = {
    id: p.id,
    title: p.title,
    url: p.url,
    labels: (p.labels || []).map(l => l.toLowerCase().trim())
  };
});

// Enriquecer cada post con su contexto de cluster
const enriched = allPosts.map(post => {
  const labels = (post.labels || []).map(l => l.toLowerCase().trim());
  const isPilar = labels.includes(LABEL_PILAR);

  // Buscar el pilar relacionado (comparte label temática + tiene label pilar)
  const topicLabels = labels.filter(l => l !== LABEL_PILAR);
  const pillar = Object.values(byId).find(p =>
    p.id !== post.id &&
    p.labels.includes(LABEL_PILAR) &&
    topicLabels.some(l => p.labels.includes(l))
  ) || null;

  // Posts hermanos en el mismo cluster
  const siblings = Object.values(byId)
    .filter(p =>
      p.id !== post.id &&
      !p.labels.includes(LABEL_PILAR) &&
      topicLabels.some(l => p.labels.includes(l))
    )
    .slice(0, 3);

  return {
    json: {
      id: post.id,
      title: post.title,
      url: post.url,
      labels,
      content: post.content || '',
      isPilar,
      isCluster: !isPilar && !!pillar,
      pillarTitle: pillar?.title || null,
      pillarUrl: pillar?.url || null,
      siblings: siblings.map(s => ({ title: s.title, url: s.url })),
      // Pasar config para usarla en los nodos siguientes
      BLOG_ID: config.BLOG_ID,
      DEEPSEEK_API_KEY: config.DEEPSEEK_API_KEY,
      SYSTEME_URL: config.SYSTEME_URL,
      BRAND_COLOR: config.BRAND_COLOR,
      BRAND_NAME: config.BRAND_NAME
    }
  };
});

return enriched;

const p = $input.item.json;

const labelsText = p.labels.filter(l => l !== 'pilar' && l !== 'pillar').join(', ') || 'blog';
const isCluster = p.isCluster && !!p.pillarTitle;

const systemMsg = `Eres un diseñador HTML/CSS experto en blogs hispanohablantes y marketing de conversión.
Siempre respondes ÚNICAMENTE con JSON válido, sin markdown, sin texto adicional.
Tus diseños son mobile-first, creativos, con emojis temáticos (nunca ✅❌), y CSS 100% inline.`;

const userMsg = `Genera 2 bloques HTML para este post:

📝 POST: "${p.title}"
🏷️ Temas: ${labelsText}
${isCluster
  ? `📌 Es post de CLUSTER. Pilar: "${p.pillarTitle}" → ${p.pillarUrl}`
  : `🏆 Es post PILAR (no necesita bloque de cluster, deja clusterBlock vacío)`
}
🔗 Funnel ventas: ${p.SYSTEME_URL}
🎨 Color marca: ${p.BRAND_COLOR} | Marca: ${p.BRAND_NAME}

Responde SOLO este JSON:
{"clusterBlock": "...", "ctaBlock": "..."}

━━━━━━━━━━━━━━━━
🔷 BLOQUE 1 — clusterBlock (vacío "" si es pilar):
• Caja 100% ancho, display:flex, flex-wrap:wrap, gap:16px, align-items:center
• Imagen izquierda: div 78x78px cuadrado, border-radius:12px,
  background: gradient 135deg de variaciones del color ${p.BRAND_COLOR},
  display:flex, align-items:center, justify-content:center,
  font-size:36px con 1 emoji relevante al tema (NO genérico)
• Texto derecho: flex:1, min-width:200px
  - Párrafo con 2 emojis del nicho + texto que diga que hay más en el pilar (2 líneas)
  - Ej: "💡🔍 ¿Quieres dominar ${labelsText} de verdad? Esta es solo una pieza del rompecabezas."
  - Link bold → color ${p.BRAND_COLOR}, text-decoration:none:
    "Leer la guía completa: ${isCluster ? p.pillarTitle : ''} →"
• Estilos caja: background:#f8faff, border-left:5px solid ${p.BRAND_COLOR},
  border-radius:0 10px 10px 0, padding:20px, margin:28px 0
• Marcadores: inicia con <!-- CLUSTER_BLOCK --> termina con <!-- /CLUSTER_BLOCK -->

━━━━━━━━━━━━━━━━
🔶 BLOQUE 2 — ctaBlock (siempre presente):
• Contenedor: background gradient 135deg ${p.BRAND_COLOR} hacia versión oscurecida,
  border-radius:14px, padding:28px 24px, margin:32px 0,
  text-align:center, box-shadow:0 8px 30px rgba(0,0,0,0.18)
• Imagen cuadrada arriba centrada: 90x90px, border-radius:14px,
  background:gradient contrastante (blanco semitransparente), display:inline-flex,
  align-items:center, justify-content:center,
  font-size:44px con emoji del nicho ${labelsText}, margin:0 auto 16px
• Título: 1 línea, color:#fff, font-weight:800, font-size:1.35em,
  margin:0 0 10px, con emoji de urgencia/valor al inicio (🔥 💡 🎯 o relacionado al nicho)
• 2 bullets: lista sin viñetas, color:rgba(255,255,255,0.88), font-size:0.95em,
  cada línea empieza con emoji específico del nicho (no checkmarks)
• Botón: display:inline-block, background:#fff, color:${p.BRAND_COLOR},
  padding:14px 36px, border-radius:50px, font-weight:800, font-size:1.05em,
  text-decoration:none, margin-top:20px,
  box-shadow:0 4px 18px rgba(0,0,0,0.2),
  href="${p.SYSTEME_URL}", texto: acción concreta y específica del nicho
• Marcadores: inicia con <!-- CTA_BLOCK --> termina con <!-- /CTA_BLOCK -->`;

return {
  json: {
    ...p,
    _deepseekBody: JSON.stringify({
      model: 'deepseek-chat',
      messages: [
        { role: 'system', content: systemMsg },
        { role: 'user',   content: userMsg   }
      ],
      max_tokens: 2500,
      temperature: 0.75,
      response_format: { type: 'json_object' }
    })
  }
};

// DeepSeek response está en el item actual
// Datos originales del post están en el nodo 'Construir Prompt DeepSeek'
const dsItem = $input.item.json;
const postData = $('🧠 Construir Prompt DeepSeek').item.json;

// --- Parsear respuesta de DeepSeek ---
let rawContent = '';
try {
  rawContent = dsItem.choices[0].message.content || '';
} catch(e) {
  rawContent = '';
}

// Limpiar posible markdown
const cleaned = rawContent
  .replace(/```json\s*/gi, '')
  .replace(/```\s*/gi, '')
  .trim();

let clusterBlock = '';
let ctaBlock = '';

try {
  const parsed = JSON.parse(cleaned);
  clusterBlock = (parsed.clusterBlock || '').trim();
  ctaBlock     = (parsed.ctaBlock     || '').trim();
} catch(e) {
  // Fallback: extraer por marcadores si el JSON falló
  const cm = cleaned.match(/<!-- CLUSTER_BLOCK -->[\s\S]*?<!-- \/CLUSTER_BLOCK -->/);
  const tm = cleaned.match(/<!-- CTA_BLOCK -->[\s\S]*?<!-- \/CTA_BLOCK -->/);
  clusterBlock = cm ? cm[0] : '';
  ctaBlock     = tm ? tm[0] : '';
}

// --- Inyectar en el contenido del post ---
let content = postData.content || '';

// Helper: reemplazar o insertar bloque
function upsertBlock(html, content, startTag, endTag, insertAtPosition) {
  if (!html) return content;
  const regex = new RegExp(startTag.replace(/[.*+?^${}()|[\]\\]/g, '\\$&') + '[\\s\\S]*?' + endTag.replace(/[.*+?^${}()|[\]\\]/g, '\\$&'), 'g');
  if (content.includes(startTag)) {
    return content.replace(regex, html);
  }
  // Insertar en posición calculada
  if (insertAtPosition === 'end') {
    return content + '\n' + html;
  }
  // Para clusterBlock: insertar al 65% del contenido
  const cutIdx = Math.floor(content.length * 0.65);
  const anchor = content.lastIndexOf('</p>', cutIdx);
  const insertAt = anchor > 0 ? anchor + 4 : cutIdx;
  return content.slice(0, insertAt) + '\n' + html + '\n' + content.slice(insertAt);
}

// 1. Bloque cluster→pilar (al 65% del artículo)
content = upsertBlock(clusterBlock, content, '<!-- CLUSTER_BLOCK -->', '<!-- /CLUSTER_BLOCK -->', 'middle');

// 2. CTA de ventas (al final)
content = upsertBlock(ctaBlock, content, '<!-- CTA_BLOCK -->', '<!-- /CTA_BLOCK -->', 'end');

return {
  json: {
    id:         postData.id,
    title:      postData.title,
    BLOG_ID:    postData.BLOG_ID,
    newContent: content,
    isCluster:  postData.isCluster,
    isPilar:    postData.isPilar,
    hasCluster: clusterBlock.length > 0,
    hasCTA:     ctaBlock.length > 0
  }
};

const items = $input.all();
const total = items.length;
return [{
  json: {
    status: '✅ Blog Factory completado',
    postsAnalizados: total,
    timestamp: new Date().toLocaleString('es-MX', { timeZone: 'America/Mexico_City' }),
    nota: `${total} posts procesados. Bloques cluster + CTA inyectados via DeepSeek.`
  }
}];
